"""Offline annotation UI. Downloads explicit review JSON; never submits it."""
import argparse
import json
from pathlib import Path


def write_review_view(tasks, destination):
    data = json.dumps(tasks).replace("<", "\\u003c").replace("&", "\\u0026")
    destination = Path(destination)
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_text(PAGE.replace("__TASKS__", data))


PAGE = r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Agere · Teach the evidence specialist</title>
<style>*{box-sizing:border-box}body{margin:0;background:#f4f5ed;color:#183330;font:15px/1.5 system-ui,sans-serif}header{padding:20px 5vw;border-bottom:1px solid #cbd9cc;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}.brand{font-size:26px;font-weight:650;letter-spacing:-1px}main{max-width:1280px;padding:35px;margin:auto}h1{font:38px/1.15 Georgia,serif;font-weight:400;margin-top:0}.muted{color:#526961}.layout{display:grid;grid-template-columns:minmax(0,1fr) 350px;gap:28px}section,aside{min-width:0}aside{position:sticky;top:20px;align-self:start;background:#fffefa;border:1px solid #cbd9cc;border-radius:8px;padding:22px}button,input,select,textarea{font:inherit}button{cursor:pointer;border:1px solid #9ab09f;padding:9px 13px;border-radius:5px;background:white;color:#183330}button.primary{background:#183330;color:white}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #b7780d;outline-offset:2px}input[type=text],select,textarea{width:100%;padding:9px;background:white;border:1px solid #b4c7b7;border-radius:4px;margin:5px 0 17px}textarea{min-height:100px}label{font-size:13px}.nav{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:22px 0}.record{background:white;border:1px solid #d5dfd5;border-radius:6px;margin:12px 0;padding:14px}.record summary{cursor:pointer}.record pre{font:13px/1.6 ui-monospace,monospace;white-space:pre-wrap;overflow-wrap:anywhere;max-height:480px;overflow:auto;border-top:1px solid #d5dfd5;padding-top:14px}.ref{display:block;margin-top:10px;color:#136853}.error{color:#922c28;min-height:24px}.status{font:12px ui-monospace,monospace}.hint{background:#e7ecdf;padding:12px;font-size:13px;margin:15px 0}button:disabled{opacity:.45;cursor:default}@media(max-width:850px){main{padding:22px}.layout{grid-template-columns:1fr}aside{position:static}h1{font-size:30px}}
</style><header><div class="brand">agere.</div><span>SYNTHETIC TRAINING REVIEW · OFFLINE</span></header><main><h1>Teach the difference.<br>Keep the evidence.</h1><p class="muted">Review what these synthetic records support. Your labels can train different model families. No records or decisions leave this page automatically.</p><div class="nav"><button id="prev">← Previous</button><span id="position" class="status"></span><button id="next">Next →</button><button id="download" class="primary">Download completed reviews</button></div><div class="hint">Pending labels are not training data. Changes are held in this tab's memory; download them before closing. This view creates initial reviews; revising an imported review requires its previous revision ID through the command-line workflow.</div><div class="layout"><section><h2 id="subject"></h2><p id="scope" class="muted"></p><div id="evidence"></div></section><aside><label for="reviewer">Reviewer name / identifier</label><input id="reviewer" type="text" autocomplete="off"><label for="label">What do the records establish?</label><select id="label"><option value="">Choose a label…</option></select><p id="meaning" class="muted"></p><label for="rationale">Reason for this decision</label><textarea id="rationale" placeholder="Explain the evidence, time relationship or information that is missing."></textarea><p class="muted" style="font-size:12px">Check the supporting records on the left. A documented record does not prove present use or clinical appropriateness.</p><button id="save" class="primary">Save review in this tab</button><button id="exclude">Exclude example</button><p id="message" class="error" role="status"></p><details><summary>Inspect baseline proposal</summary><p id="proposal"></p><p class="muted">Unreviewed machine proposal; not ground truth.</p></details></aside></div></main><script type="application/json" id="tasks">__TASKS__</script>
<script>
const tasks=JSON.parse(document.getElementById('tasks').textContent),reviews=new Map();let index=0;const $=x=>document.getElementById(x);function node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n}
const options=tasks[0]?.label_options||{};for(const [value,meaning]of Object.entries(options)){const o=node('option',value.replaceAll('_',' '));o.value=value;$('label').append(o)}
function render(){const t=tasks[index];$('message').textContent='';if(!t){$('subject').textContent='No review tasks';$('save').disabled=$('exclude').disabled=$('next').disabled=$('prev').disabled=true;return}const saved=reviews.get(t.task_id);$('position').textContent=`${index+1} / ${tasks.length} · ${reviews.size} reviewed`; $('subject').textContent=`${t.input.subject.toUpperCase()} · ${t.origin.patient_id}`;$('scope').textContent=`${t.origin.world} · ${t.origin.split} partition · research window ${t.input.window_start} through ${t.input.as_of}. ${t.input.source_coverage}.`;$('label').value=saved?.label||'';$('rationale').value=saved?.rationale||'';$('meaning').textContent=options[$('label').value]||'';$('proposal').textContent=t.proposal.state.replaceAll('_',' ');$('evidence').replaceChildren();if(!t.input.evidence.length)$('evidence').append(node('p','No source records in this task. Absence of records does not establish absent care.'));for(const e of t.input.evidence){const d=node('div',undefined,'record'),details=node('details'),r=e.record;details.append(node('summary',`${e.id} · ${e.source} · ${r.date||r.fill_date||r.result_date||'date unknown'}`),node('pre',r.text||JSON.stringify(r,null,2)));d.append(details);const label=node('label',undefined,'ref'),check=document.createElement('input');check.type='checkbox';check.value=e.id;check.className='support';check.checked=!!saved?.support_ids.includes(e.id);label.append(check,document.createTextNode(' Use as supporting evidence'));d.append(label);$('evidence').append(d)}$('prev').disabled=index===0;$('next').disabled=index===tasks.length-1}
function save(exclude=false){const t=tasks[index];if(!t)return;const reviewer=$('reviewer').value.trim(),rationale=$('rationale').value.trim(),label=exclude?null:$('label').value,support=exclude?[]:[...document.querySelectorAll('.support:checked')].map(e=>e.value);if(!reviewer||!rationale||(!exclude&&!label)){ $('message').textContent='Provide your identifier, a rationale and a label (unless excluding).';return}if(!exclude&&label!=='insufficient_evidence'&&!support.length){$('message').textContent='Select at least one supporting source record.';return}reviews.set(t.task_id,{task_id:t.task_id,previous_revision:null,decision:exclude?'exclude':label===t.proposal.state?'accept':'correct',label,support_ids:support,reviewer,reviewer_kind:'human',reviewed_at:new Date().toISOString(),rationale});$('position').textContent=`${index+1} / ${tasks.length} · ${reviews.size} reviewed`;$('message').textContent='Saved in this tab. Download to retain and import this review.'}
$('save').onclick=()=>save();$('exclude').onclick=()=>save(true);$('prev').onclick=()=>{index--;render()};$('next').onclick=()=>{index++;render()};$('label').onchange=()=>{$('meaning').textContent=options[$('label').value]||''};$('download').onclick=()=>{if(!reviews.size){$('message').textContent='No completed reviews to download.';return}const blob=new Blob([[...reviews.values()].map(r=>JSON.stringify(r)).join('\n')+'\n'],{type:'application/x-ndjson'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='agere-reviews.jsonl';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};render();
</script></html>'''


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("queue", type=Path)
    parser.add_argument("output", type=Path)
    args = parser.parse_args()
    tasks = [json.loads(line) for line in args.queue.read_text().splitlines() if line.strip()]
    write_review_view(tasks, args.output)
    print(json.dumps({"output": str(args.output), "tasks": len(tasks), "network_calls": 0}))


if __name__ == "__main__":
    main()
